<script setup lang="ts">
import { computed, ref } from 'vue'; import { storeToRefs } from 'pinia'; import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'; import PageHeader from '@/Components/layout/PageHeader.vue'; import SiteForm from '@/Components/sites/SiteForm.vue'; import { useAdministratorStore } from '@/stores/administrator.store'; import type { SiteInput } from '@/types/administrator'
const route = useRoute(); const router = useRouter(); const store = useAdministratorStore(); const { users } = storeToRefs(store); const id = computed(() => route.params.siteId as string | undefined); const site = computed(() => id.value ? store.getSiteById(id.value) : undefined); const managers = computed(() => users.value.filter((user) => ['administrator','supervisor','teamLeader'].includes(user.role) && user.status === 'active')); const dirty = ref(false)
onBeforeRouteLeave(() => !dirty.value || window.confirm('Des modifications ne sont pas enregistrées. Voulez-vous quitter cette page ?'))
function submit(payload: SiteInput) { dirty.value = false; const siteId = id.value ? (store.updateSite(id.value, payload), id.value) : store.createSite(payload); void router.push({ name: 'admin-site-details', params: { siteId } }) }
</script>
<template><div class="mx-auto w-full max-w-[1050px]"><PageHeader><template #title>{{ id ? 'Modifier le site' : 'Nouveau site' }}</template><template #description>Définissez le lieu et la zone de présence autorisée.</template><template #actions><v-btn variant="text" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-sites' }">Retour</v-btn></template></PageHeader><v-alert v-if="id && !site" type="error" variant="tonal" title="Site introuvable" /><SiteForm v-else :site="site" :managers="managers" @submit="submit" @cancel="router.back()" @dirty-change="dirty = $event" /></div></template>

